    const webNode = $('SAST from Website').first();
    if (webNode && webNode.json.body && webNode.json.body.staff_id) {
      staffId = webNode.json.body.staff_id;
    }
  } catch (error) {
    // Not a website execution
  }
}

// Attempt 3: 'sast-manual-correction' node
try {
  const manualNode = $('sast-manual-correction1').first();
  if (manualNode) {
    // If this node executed without throwing an error, we know it's a manual correction!
    isManuallyCorrected = true; 

    // Check for the user_id in the manual correction payload if we don't have a staffId yet
    if (!staffId && manualNode.json.body && manualNode.json.body.user_id) {
      staffId = manualNode.json.body.user_id;
    }
  }
} catch (error) {
  // Node didn't run, meaning this is an automated run
}

// website rows are already stored, so skip the shared upsert
let websiteRawStored = false;
