  const w = $('Website Raw Upsert').first();
  websiteRawStored = !!(w && w.json && w.json.saved === true);
} catch (error) {
  // Not a website execution
}

// Map the raw data and include the new database flags
const rawData = $input.all().map(item => {
  const r = item.json;
  return {
    json: {
      instructor_ID: r['instructor_ID'] || null,
      subject_id: r['true_subject_id'] || null,
      term_id: r['current_term_id'] || null,
      // blank student id -> NULL so it never matches another row
      student_id: (typeof r['Student ID'] === 'string' ? r['Student ID'].trim() : r['Student ID']) || null,
      instructor: r['Instructor/Professor'] || null,

      m1: Number(r['M1']) || null,
      m2: Number(r['M2']) || null,
      m3: Number(r['M3']) || null,
      m4: Number(r['M4']) || null,
      m5: Number(r['M5']) || null,
      m6: Number(r['M6']) || null,
      m7: Number(r['M7']) || null,
      m8: Number(r['M8']) || null,
      m9: Number(r['M9']) || null,
      m10: Number(r['M10']) || null,

      p1: Number(r['P1']) || null,
      p2: Number(r['P2']) || null,
      p3: Number(r['P3']) || null,
      p4: Number(r['P4']) || null,
      p5: Number(r['P5']) || null,
      p6: Number(r['P6']) || null,
      p7: Number(r['P7']) || null,
      p8: Number(r['P8']) || null,
      p9: Number(r['P9']) || null,
      p10: Number(r['P10']) || null,

      // mask sexual words before storing
      Remarks_and_Suggestions: maskProfanity(String(r['Remarks & Suggestions'] ?? '').trim()) || null,

      submitted_date: r['Date'] ? new Date(r['Date']).toISOString().split('T')[0] : null,

      sao_staff_id: staffId,

      // ADDED: Map to the columns shown in your Supabase screenshot
      manually_corrected: isManuallyCorrected,
      validation_status: isManuallyCorrected ? 'corrected' : 'auto',

      // only when present, so sheet imports never clear task_id
      ...(r['task_id'] && !Array.isArray(r['task_id']) ? { task_id: String(r['task_id']) } : {}),
      ...(websiteRawStored ? { _raw_already_stored: true } : {})
    }
  };
});

const uniqueData = [];
const seen = new Set();

// Loop backwards to keep the newest submission and discard older duplicates
for (let i = rawData.length - 1; i >= 0; i--) {
  const item = rawData[i];
  const j = item.json;

  // The magic fingerprint checking Student + Instructor + Subject + Term
  const uniqueKey = `${j.student_id}_${j.instructor_ID}_${j.subject_id}_${j.term_id}`;

  // rows without a student id are never deduped
  if (j.student_id === null || !seen.has(uniqueKey)) {
    seen.add(uniqueKey);
    uniqueData.push(item);
  }
}

return uniqueData.reverse();

// Grab ALL 205 items from the If node
const allItems = $('If1').all();
const uniquePairs = {};

// Loop through all of them and find every unique Instructor + Term combo
for (const item of allItems) {
  const instId = item.json.instructor_ID;
  const termId = item.json.current_term_id;

  if (instId && termId) {
    uniquePairs[`${instId}_${termId}`] = {
      instructor_id: instId,
      term_id: termId
    };
  }
}

// Return the full list of unique instructors so Postgres updates ALL of them
return Object.values(uniquePairs).map(pair => ({ json: pair }));

const items = $input.all();

return items.map(item => {
  // n8n Webhook data is usually inside item.json.body
  const payload = item.json.body || item.json;

  const staffId = payload.user_id;
  const googleLink = payload.link;
  let sheetId = '';

  if (googleLink && typeof googleLink === 'string') {
    const match = googleLink.match(/\/d\/(.*?)(\/|$)/);
    if (match && match[1]) {
      sheetId = match[1];
    }
  }

  return {
    json: {
      staff_id: staffId,
      google_link: googleLink,
      sheetId: sheetId,  // Changed this so the Google Node recognizes it automatically!
      import_type: payload.type,
      sync_time: payload.timestamp
    }
  };
});

// Reads the RECONCILED result, not the raw Python output.
//
// Before: this pulled ratings.management[] / ratings.performance[] straight from
// the Python service, and referenced a node that has since been deleted, so it
// threw on every run. Reading Python directly also threw away every bubble the
// reconciler recovered from Gemini.
const rec = $('reconcile ocr and omr1').first().json;

const ratings = rec.ratings ?? {};
const result = {};

// The reconciler emits a flat object, m1..m10 / p1..p10, where null means both
// engines agreed the row is genuinely blank. Downstream arithmetic sums these,
// so a blank has to become 0, not null.
let answered = 0;
let sum = 0;
for (let i = 1; i <= 10; i++) {
  for (const prefix of ['m', 'p']) {
    const key = `${prefix}${i}`;
    const v = ratings[key];
    const score = (v === null || v === undefined) ? 0 : Number(v) || 0;
    result[key] = score;
    if (score > 0) { answered++; sum += score; }
  }
}

// Recomputed from the reconciled values. Python's own summary predates the
// blank-filling, so reusing it would disagree with the scores just above it.
result.answered    = answered;
result.total_score = sum;
result.average     = answered ? Number((sum / answered).toFixed(2)) : 0;
result.percent     = Number(((sum / (20 * 5)) * 100).toFixed(2));

result.grid_source = rec.grid_source ?? null;
result.table_found = rec.table_found ?? null;

// OCR text: Gemini-first, already decided by the reconciler.
result.cleaned_remarks = rec.remarks ?? '';

// Carried so the run data shows whether anything cross-checked this scan.
result.validation_status = rec.validation_status ?? 'auto';
result.review_reasons    = rec.review_reasons ?? [];

return [{ json: result }];

const link = $input.first().json.body.link;
const termId = $input.first().json.body.term_id;
const userId = $input.first().json.body.user_id;

const match = link.match(/\/spreadsheets\/d\/([a-zA-Z0-9-_]+)/);
if (!match) throw new Error('Invalid Google Sheet URL');
const sheetId = match[1];

const gidMatch = link.match(/gid=([0-9]+)/);
const gid = gidMatch ? gidMatch[1] : '0';

const csvUrl = `https://docs.google.com/spreadsheets/d/${sheetId}/export?format=csv&gid=${gid}`;

// Added sheetId here so the next node can use {{$json.sheetId}}
return [{ json: { csvUrl, termId, userId, sheetId } }];

// Adds validation_status = auto (clean OCR/OMR result)
const items = $input.all();
return items.map(item => ({
  json: {
    ...item.json,
    validation_status: 'auto'
  }
}));

const body = $('sast-manual-correction1').first().json.body;
const instructorId = $('get instructor id7').first().json.instructor_id ?? null;
const subjectId    = $('get subject id6').first().json.subject_id ?? null;

// Safety: convert [null] arrays from Flutter → actual null
const termId  = Array.isArray(body.term_id)  ? null : (body.term_id  ?? null);
const userId  = Array.isArray(body.user_id)  ? null : (body.user_id  ?? null);
const taskId  = Array.isArray(body.task_id)  ? null : (body.task_id  ?? null);

const scores = {};
for (let i = 1; i <= 10; i++) {
  scores[`m${i}`] = parseInt(body[`m${i}`]) || 0;
  scores[`p${i}`] = parseInt(body[`p${i}`]) || 0;
}

return [{
  json: {
    raw: {
      instructor:              body.instructor ?? '',
      student_id:              body.student_id ?? '',
      Remarks_and_Suggestions: body.remarks    ?? '',
      submitted_date:          new Date().toISOString().split('T')[0],
      sao_staff_id:            userId,       // ← safe, no [null]
      term_id:                 termId,       // ← safe, no [null]
      instructor_ID:           instructorId,
      subject_id:              subjectId,
      task_id:                 taskId,       // ← safe, no [null]
      manually_corrected:      true,
      validation_status:       'corrected',
      ...scores,
    },
    instructor_ID:  instructorId,
    subject_id:     subjectId,
    term_id:        termId,
    failed_scan_id: body.failed_scan_id,
    scores,
  }
}];

