    const mean = total / data.count;
    totalsOut[`m${i}_total`] = total;     // ← m not p
    means[`m${i}_mean`] = Number(mean.toFixed(2));
    sumMeans += mean;
    grandTotal += total;
  }

  const overall_management_mean = Number((grandTotal / (data.count * 10)).toFixed(2));
  const average_per_response_management = Number((grandTotal / data.count).toFixed(2));

  output.push({
    json: {
      instructor_id: data.instructor_id,
      term_id: data.term_id,
      subject_id: data.subject_id,
      total_responses: data.count,
      ...totalsOut,
      grand_total: grandTotal,
      ...means,
      overall_management_mean,
      average_per_response_management
    }
