  throw new Error("Gemini JSON parsing failed: " + error.message);
}

const original = $("Prepare Individual AI Input1").item.json;

const output = [];

let tone = result.overall_tone || "Neutral";

if (!["Positive", "Critical", "Neutral"].includes(tone)) {
  tone = "Neutral";
}

// Safety net: guarantee at least 1 wordcloud keyword even if Gemini returns none
let keywords = result.keywords || [];
// skip keywords with sexual or masked words
if (Array.isArray(keywords)) keywords = keywords.filter((k) => !(k && profaneKeyword(String(k.word ?? ''))));

if (keywords.length === 0) {
  const fallbackWord =
    tone === "Positive" ? "Positive feedback" :
    tone === "Critical" ? "Needs improvement" :
    "General feedback";

  keywords = [{ word: fallbackWord, count: 1 }];
}

for (const keyword of keywords) {

  if (!keyword.word) continue;

  output.push({
    json: {
      record_type: "wordcloud",

      instructor_id: original.instructor_ID,
      term_id: original.term_id,

      word: String(keyword.word).trim(),
      count: 1
    }
  });
}


output.push({
  json: {
    record_type: "student_remark",

    instructor_ID: original.instructor_ID,
    subject_id: original.subject_id,
    term_id: original.term_id,

    remark: maskProfanity(original.new_student_remark),
    tone
  }
});

// mask sexual words in the AI output too
for (const k of ['ai_suggestion', 'student_interpretation', 'positive_themes', 'improvement_insights']) {
  if (typeof result[k] === 'string') result[k] = maskProfanity(result[k]);
  else if (Array.isArray(result[k])) result[k] = result[k].map((v) => (typeof v === 'string' ? maskProfanity(v) : v));
}

output.push({
  json: {
    record_type: "evaluation",

    instructor_id: original.instructor_ID,
    term_id: original.term_id,

    ai_suggestion: result.ai_suggestion || "",
    student_interpretation: result.student_interpretation || "",
    positive_themes: result.positive_themes || [],
    improvement_insights: result.improvement_insights || [],
    overall_tone: tone
  }
});

return output;

