  // 1. Map IDs
  result["instructor_ID"] = instructorDbData.instructor_id || null;
  result["true_subject_id"] = subjectDbData.subject_id || null;
  result["current_term_id"] = data.current_term_id || null;
  result["scan_image"] = separateData.scan_image || null;
  result["review_reasons"] = separateData.review_reasons || [];
  result["omr_comparisons"] = separateData.comparisons || null;
  result["review_note"] = separateData.review_note || null;
  result["task_id"] = separateData.task_id || null;

  // 2. Map standard text fields
  result["Student ID"] =  separateData.student_id || "";
  const rawInstructorName = separateData.instructor || "";
  const firstName = instructorDbData.first_name || "";
  const lastName = instructorDbData.last_name || "";
  const dbInstructorName = `${firstName} ${lastName}`.trim();
  result["Instructor/Professor"] = dbInstructorName || rawInstructorName;
  result["Subject Taught"] = subjectDbData.subject_name || separateData.subject || "";
  result["AY/Semester"] = (data.academic_terms?.semester || "") + " " + (data.academic_terms?.academic_year || "");
  result["Remarks & Suggestions"] = separateData.remarks || "";
  result["Date"] = todayFormatted;

  // 3. Map OMR Scores
  for (let i = 1; i <= 10; i++) {
    result[`M${i}`] = formattedResults[`m${i}`] !== undefined ? formattedResults[`m${i}`] : 0;
    result[`P${i}`] = formattedResults[`p${i}`] !== undefined ? formattedResults[`p${i}`] : 0;
  }

  newItems.push({ json: result });
}

return newItems;

